#include <vector>
#include <unordered_set>

class Solution {
public:
    int maxNonOverlapping(std::vector<int>& nums, int target) {
        std::unordered_set<int> seen;
        seen.insert(0);
        int cur = 0, ans = 0;
        for (int x : nums) {
            cur += x;
            if (seen.count(cur - target)) {
                ans++;
                seen.clear();
                seen.insert(cur);
            } else {
                seen.insert(cur);
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int maxNonOverlapping(int[] nums, int target) {
        Set<Integer> seen = new HashSet<>();
        seen.add(0);
        int cur = 0, ans = 0;
        for (int x : nums) {
            cur += x;
            if (seen.contains(cur - target)) {
                ans++;
                seen.clear();
                seen.add(cur);
            } else {
                seen.add(cur);
            }
        }
        return ans;
    }
}

